[SERVICE]
  Daemon Off
  Flush {{ .Values.flush }}
  Log_Level {{ .Values.logLevel }}
  Parsers_File /fluent-bit/etc/parsers.conf
  Parsers_File /fluent-bit/etc/conf/custom_parsers.conf
  HTTP_Server On
  HTTP_Listen 0.0.0.0
  HTTP_Port {{ .Values.metricsPort }}
  Health_Check On

discovery.kubernetes "pod" {
  role = "pod"
  selectors {
    role  = "pod"
    field = "spec.nodeName=" + sys.env("NODE_NAME")
  }
}

discovery.relabel "pod_logs" {
  targets = discovery.kubernetes.pod.targets

  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    action        = "replace"
    target_label  = "namespace"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    action        = "replace"
    target_label  = "pod"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "container"
  }

  rule {
    source_labels = ["__meta_kubernetes_namespace", "__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "job"
    separator     = "/"
    replacement   = "$1"
  }

  rule {
    source_labels = ["__meta_kubernetes_pod_uid", "__meta_kubernetes_pod_container_name"]
    action        = "replace"
    target_label  = "__path__"
    separator     = "/"
    replacement   = "/var/log/pods/*$1/*.log"
  }
}

loki.source.kubernetes "pod_logs" {
  targets    = discovery.relabel.pod_logs.output
  forward_to = [loki.process.pod_logs.receiver]
}

loki.source.kubernetes_events "events" {
  forward_to = [loki.process.kubernetes_events.receiver]
}

// Talos kernel/service logs forwarded over TCP syslog from each node's machined.
// Receives Talos json_lines format; syslog parse is best-effort — raw JSON lines
// are stored as-is and can be parsed at query time (LogsQL: | unpack_json).
// Requires machine.logging.destinations configured via talosctl apply-config.
loki.source.syslog "talos" {
  listener {
    address  = "0.0.0.0:6514"
    protocol = "tcp"
    labels   = {
      job     = "talos/kernel",
      cluster = "homelab-cluster",
      node    = sys.env("NODE_NAME"),
    }
  }
  forward_to = [loki.write.local.receiver]
}

loki.process "pod_logs" {
  stage.static_labels {
    values = {
      cluster = "homelab-cluster",
    }
  }

  // Dark factory: promote ploegd/worker logfmt payload keys to first-class
  // VictoriaLogs fields (structured metadata -> ordinary VL fields, NOT
  // labels — per-line values like trace_id must stay out of _stream_fields).
  // logfmt parse is lenient: lines without these keys (postgres JSON, dind)
  // simply contribute nothing. Scoped to ns ploeg — other namespaces untouched.
  stage.match {
    selector = "{namespace=\"ploeg\"}"

    stage.logfmt {
      mapping = {
        outcome     = "",
        team        = "",
        title       = "",
        links       = "",
        budget      = "",
        trace_id    = "trace",
        wi_id       = "id",
        work_item   = "",
        external_id = "",
        role        = "",
        shift       = "",
        round       = "",
      }
    }

    stage.structured_metadata {
      values = {
        outcome     = "",
        team        = "",
        title       = "",
        links       = "",
        budget      = "",
        trace_id    = "",
        wi_id       = "",
        work_item   = "",
        external_id = "",
        role        = "",
        shift       = "",
        round       = "",
      }
    }
  }

  forward_to = [loki.write.local.receiver]
}

loki.process "kubernetes_events" {
  stage.static_labels {
    values = {
      cluster = "homelab-cluster",
      job     = "kubernetes/events",
    }
  }

  forward_to = [loki.write.local.receiver]
}

// VictoriaLogs speaks the Loki push protocol natively; _stream_fields pins
// today's Loki stream shape explicitly (fields absent on an entry are
// ignored, so one list serves pod logs + events + Talos syslog).
loki.write "local" {
  endpoint {
    url = "http://vlsingle-victorialogs.observability.svc.cluster.local:9428/insert/loki/api/v1/push?_stream_fields=cluster,namespace,pod,container,job,node,instance"
  }
}

local.file_match "kube_audit" {
  path_targets = [{
    __path__ = "/var/log/audit/kube/kube-apiserver.log",
    job      = "kube-audit",
    cluster  = "homelab-cluster",
    node     = sys.env("NODE_NAME"),
  }]
}

loki.source.file "kube_audit" {
  targets    = local.file_match.kube_audit.targets
  forward_to = [loki.process.kube_audit.receiver]
}

loki.process "kube_audit" {
  stage.json {
    expressions = {
      verb        = "verb",
      user        = "user.username",
      resource    = "objectRef.resource",
      subresource = "objectRef.subresource",
    }
  }
  stage.labels {
    values = { verb = "", resource = "", subresource = "", user = "" }
  }
  stage.match {
    selector = "{user=~\"system:.*\", verb=~\"get|list|watch\", resource!~\"secrets|serviceaccounts|.*roles|.*rolebindings|certificatesigningrequests\", subresource!~\"exec|attach|portforward\"}"
    action   = "drop"
  }
  stage.match {
    selector = "{subresource=\"status\", verb=~\"update|patch\"}"
    action   = "drop"
  }
  stage.label_drop {
    values = ["verb", "resource", "subresource", "user"]
  }
  forward_to = [loki.write.audit.receiver]
}

loki.write "audit" {
  endpoint {
    url = "http://vlsingle-victorialogs-audit.observability.svc.cluster.local:9428/insert/loki/api/v1/push?_stream_fields=cluster,job,node&_msg_field=requestURI"
  }
}
